(* [comment removed for export] *)
Lemma rdn_of_bytes1 : forall M n (a : word) bs,
  length bs = n -> bv_unsigned a + Z.of_nat n <= 2 ^ 64 ->
  (forall j, (j < n)%nat -> rdn SEGS M (Z_to_bv 64 (bv_unsigned a + Z.of_nat j)) 1 = Some [nth j bs (Z_to_bv 8 0)]) ->
